public class Student {
    // attributes, what every Student has
    String name;
    int age;
    double grade;

    // behavior, what every Student can do
    void display() {
        System.out.println(name + " (" + age + "), grade: " + grade);
    }
}

public class SchoolDemo {
    public static void main(String[] args) {
        Student ana = new Student();      // one object
        ana.name = "Ana Reyes";
        ana.age = 19;
        ana.grade = 92.5;

        Student jess = new Student();     // a second, entirely separate object
        jess.name = "Jess Diaz";
        jess.age = 20;
        jess.grade = 88.0;

        ana.display();
        jess.display();
    }
}

Student ana = new Student();
ana.grade = 70;

